Object.assign(SNIP,{});PRESET_NOTES["l32"]={"Ví dụ: Tập hợp luôn sắp xếp": "Dù thêm theo thứ tự lộn xộn, tập hợp luôn sắp tăng dần và không có phần tử trùng. Phần tử nhỏ nhất là *s.begin(), lớn nhất là *prev(s.end()) (phần tử ngay trước end(); cũng viết được *s.rbegin()). Duyệt for luôn theo thứ tự tăng.", "Ví dụ: Tìm hàng xóm của x": "lower_bound(25) trỏ vào 30; lùi một bước là 20. Sau khi thêm 25, lower_bound(25) chính là 25. Mỗi lần hỏi O(log n) dù tập thay đổi liên tục.", "Ví dụ: Từ điển duyệt theo thứ tự khóa": "Giống unordered_map ở Bài 31, nhưng duyệt ra theo thứ tự chữ cái của khóa: ca, cho, ga, meo, vit. Không cần sắp xếp thêm.", "Ví dụ: Tập hợp cho phép trùng": "multiset giữ cả các phần tử trùng, vẫn luôn sắp xếp. Chú ý: erase(giá trị) xóa mọi bản sao, erase(s.find(x)) chỉ xóa một. Kết quả 6 3, rồi 2, rồi 1 4 4."};EX_HINTS["l32"]=[["Giữ tập các phòng trống, có thứ tự.", "TAKE x: lower_bound(x) cho phòng trống nhỏ nhất ≥ x; bằng end() thì không có.", "Nhớ xóa phòng vừa giao khỏi tập."], ["map giữ các khóa theo thứ tự tăng: duyệt là ra đúng thứ tự từ điển.", "tong[ten] += d tự tạo khóa mới với giá trị 0.", "Dùng unordered_map thì phải chép ra rồi sắp xếp mới in được."], ["Hiệu nhỏ nhất của cả tập chỉ có thể giảm khi thêm x, và nếu giảm thì cặp mới là x với hàng xóm gần nhất bên trái hoặc bên phải của x.", "Hàng xóm phải: lower_bound(x); hàng xóm trái: prev của nó (nếu không phải begin()).", "Giữ best qua các lần thêm; tổng O(n log n)."]];
/* ===================== BÀI 32 · set và map (cây cân bằng) so với bảng băm ===================== */
/* Bài 32 · set và map (cây cân bằng) so với bảng băm
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR32=[{label:"Ví dụ: Tập hợp luôn sắp xếp",input:"",code:"#include <iostream>\n#include <set>\nusing namespace std;\n\nint main() {\n    set<int> s;\n    int a[7] = {5, 1, 9, 3, 7, 3, 1};\n    for (int i = 0; i < 7; i++) s.insert(a[i]);   // trùng thì bỏ qua\n    cout << s.size() << \" \" << *s.begin() << \" \" << *prev(s.end()) << \"\\n\";\n    s.erase(9);\n    for (int x : s) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a",ptr:["i"]},{type:"cont",of:"s"}],py:{code:"from bisect import bisect_left, insort\n\ns = []                       # list luôn giữ thứ tự tăng, không trùng\na = [5, 1, 9, 3, 7, 3, 1]\nfor x in a:\n    i = bisect_left(s, x)\n    if i == len(s) or s[i] != x:   # chưa có x thì mới chèn\n        s.insert(i, x)\nprint(len(s), s[0], s[-1])\ns.remove(9)\nprint(*s)",viz:[{type:"cont",of:"s",as:"set",label:"s (list đã sắp xếp)"}],note:"Python không có tập hợp có thứ tự sẵn: dùng list luôn sắp xếp. bisect_left tìm vị trí trong O(log n); chèn bằng insert phải dời các phần tử phía sau (O(n)) nhưng rất nhanh trong thực tế. Nhỏ nhất là s[0], lớn nhất là s[-1]."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        SortedSet<int> s = new SortedSet<int>();\n        int[] a = { 5, 1, 9, 3, 7, 3, 1 };\n        foreach (int x in a) s.Add(x);           // trùng thì bỏ qua\n        Console.WriteLine(s.Count + \" \" + s.Min + \" \" + s.Max);\n        s.Remove(9);\n        foreach (int x in s) Console.Write(x + \" \");\n        Console.WriteLine();\n    }\n}",viz:[{type:"cont",of:"s",as:"set"}],note:"Dù thêm theo thứ tự lộn xộn, SortedSet luôn sắp tăng dần và không có phần tử trùng. Min, Max cho phần tử nhỏ nhất, lớn nhất. foreach luôn theo thứ tự tăng."}},{label:"Ví dụ: Tìm hàng xóm của x",input:"",code:"#include <iostream>\n#include <set>\nusing namespace std;\n\nint main() {\n    set<int> s = {10, 20, 30, 40};\n    int x = 25;\n    auto it = s.lower_bound(x);              // phần tử đầu tiên >= x\n    if (it != s.end()) cout << \"nho nhat >= x: \" << *it << \"\\n\";\n    if (it != s.begin()) cout << \"lon nhat < x: \" << *prev(it) << \"\\n\";\n    s.insert(25);\n    cout << *s.lower_bound(x) << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"s"}],py:{code:"from bisect import bisect_left, insort\n\ns = [10, 20, 30, 40]\nx = 25\nk = bisect_left(s, x)            # vị trí phần tử đầu tiên >= x\nif k < len(s):\n    print(\"nho nhat >= x:\", s[k])\nif k > 0:\n    print(\"lon nhat < x:\", s[k - 1])\ninsort(s, 25)\nprint(s[bisect_left(s, x)])",viz:[{type:"cont",of:"s",as:"set",label:"s (list đã sắp xếp)"}],note:"bisect_left(s, 25) = 2: s[2] = 30 là số nhỏ nhất ≥ 25, s[1] = 20 là số lớn nhất < 25. insort chèn 25 vào đúng chỗ để list vẫn sắp xếp."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        SortedSet<int> s = new SortedSet<int> { 10, 20, 30, 40 };\n        int x = 25;\n        var lonHon = s.GetViewBetween(x, int.MaxValue);       // các phần tử >= x\n        if (lonHon.Count > 0) Console.WriteLine(\"nho nhat >= x: \" + lonHon.Min);\n        var nhoHon = s.GetViewBetween(int.MinValue, x - 1);   // các phần tử < x\n        if (nhoHon.Count > 0) Console.WriteLine(\"lon nhat < x: \" + nhoHon.Max);\n        s.Add(25);\n        Console.WriteLine(s.GetViewBetween(x, int.MaxValue).Min);\n    }\n}",viz:[{type:"cont",of:"s",as:"set"}],note:"GetViewBetween(a, b) là các phần tử trong đoạn [a, b], vẫn sắp xếp. Phần tử nhỏ nhất ≥ 25 là 30, lớn nhất < 25 là 20. Kiểm tra Count > 0 trước: Min, Max của tập rỗng trả về 0 chứ không báo lỗi."}},{label:"Ví dụ: Từ điển duyệt theo thứ tự khóa",input:"",code:"#include <iostream>\n#include <string>\n#include <map>\nusing namespace std;\n\nint main() {\n    string w[7] = {\"meo\", \"cho\", \"ga\", \"meo\", \"vit\", \"ca\", \"ga\"};\n    map<string, int> dem;\n    for (int i = 0; i < 7; i++) dem[w[i]]++;\n    for (auto& p : dem) cout << p.first << \" \" << p.second << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"dem"}],py:{code:"w = [\"meo\", \"cho\", \"ga\", \"meo\", \"vit\", \"ca\", \"ga\"]\ndem = {}\nfor x in w:\n    dem[x] = dem.get(x, 0) + 1\nfor k in sorted(dem):            # sắp xếp các khóa khi cần in theo thứ tự\n    print(k, dem[k])",viz:[{type:"cont",of:"dem",as:"dict"}],note:"dict của Python giữ thứ tự THÊM VÀO, không phải thứ tự khóa. Muốn in theo thứ tự chữ cái thì sorted(dem) một lần, tốn O(n log n). Nếu vừa thêm vừa phải hỏi theo thứ tự liên tục, cần list sắp xếp + bisect như ví dụ trước."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] w = { \"meo\", \"cho\", \"ga\", \"meo\", \"vit\", \"ca\", \"ga\" };\n        SortedDictionary<string, int> dem = new SortedDictionary<string, int>();\n        foreach (string x in w) dem[x] = dem.GetValueOrDefault(x) + 1;\n        foreach (var kv in dem) Console.WriteLine(kv.Key + \" \" + kv.Value);\n    }\n}",viz:[{type:"cont",of:"dem",as:"dict"}],note:"Giống Dictionary ở Bài 31, nhưng duyệt ra theo thứ tự chữ cái của khóa: ca, cho, ga, meo, vit."}},{label:"Ví dụ: Tập hợp cho phép trùng",input:"",code:"#include <iostream>\n#include <set>\nusing namespace std;\n\nint main() {\n    multiset<int> s;\n    int a[6] = {4, 2, 4, 1, 4, 2};\n    for (int i = 0; i < 6; i++) s.insert(a[i]);\n    cout << s.size() << \" \" << s.count(4) << \"\\n\";\n    s.erase(s.find(4));          // xóa MỘT số 4\n    cout << s.count(4) << \"\\n\";\n    s.erase(2);                  // xóa MỌI số 2\n    for (int x : s) cout << x << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"s"}],py:{code:"from bisect import bisect_left, bisect_right, insort\n\ns = []\nfor x in [4, 2, 4, 1, 4, 2]:\n    insort(s, x)                 # list sắp xếp, giữ cả phần tử trùng\nprint(len(s), bisect_right(s, 4) - bisect_left(s, 4))\ndel s[bisect_left(s, 4)]         # xóa MỘT số 4\nprint(bisect_right(s, 4) - bisect_left(s, 4))\ns = [x for x in s if x != 2]     # xóa MỌI số 2\nprint(*s)",viz:[{type:"cont",of:"s",as:"set",label:"s (list đã sắp xếp)"}],note:"Số lần x xuất hiện trong list đã sắp xếp = bisect_right − bisect_left, O(log n). Xóa một bản sao: del s[bisect_left(s, x)]. Kết quả 6 3, rồi 2, rồi 1 4 4."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        SortedDictionary<int, int> s = new SortedDictionary<int, int>();   // giá trị → số lần\n        foreach (int x in new int[] { 4, 2, 4, 1, 4, 2 }) s[x] = s.GetValueOrDefault(x) + 1;\n        int tong = 0;\n        foreach (var kv in s) tong += kv.Value;\n        Console.WriteLine(tong + \" \" + s[4]);\n        if (--s[4] == 0) s.Remove(4);      // xóa MỘT số 4\n        Console.WriteLine(s[4]);\n        s.Remove(2);                       // xóa MỌI số 2\n        foreach (var kv in s)\n            for (int k = 0; k < kv.Value; k++) Console.Write(kv.Key + \" \");\n        Console.WriteLine();\n    }\n}",viz:[{type:"cont",of:"s",as:"dict"}],note:"C# không có multiset: dùng SortedDictionary giá trị → số lần. Xóa một bản sao là giảm đếm (đếm về 0 thì Remove khóa). Kết quả 6 3, rồi 2, rồi 1 4 4."}}];
